<template><q-page class="q-pa-lg"><div class="row items-center"><div><div class="page-title">{{employee?'My Leave Requests':'Team Leave Requests'}}</div><div class="muted">{{employee?'Plan and track your time away.':'Review leave requests from your direct team.'}}</div></div><q-space/><q-btn v-if="employee" color="primary" unelevated rounded icon="add" label="Apply for Leave" @click="open"/></div><div class="row q-col-gutter-md q-mt-lg"><div class="col-6 col-md-3"><q-select v-model="filter" :options="statuses" clearable outlined rounded dense label="Status"/></div></div><q-card flat bordered class="q-mt-lg"><q-table :rows="rows" :columns="cols" row-key="id" :loading="loading"><template #body-cell-status="p"><q-td><q-badge :color="color(p.row.status)" :label="p.row.status"/></q-td></template><template #body-cell-actions="p"><q-td><q-btn flat round icon="visibility" @click="router.push(`/leaves/${p.row.id}`)"/><q-btn v-if="employee&&p.row.status==='Pending'" flat round icon="cancel" color="negative" @click="cancel(p.row)"/><q-btn v-if="!employee&&p.row.status==='Pending'" flat round icon="check" color="positive" @click="review(p.row,'Approved')"/><q-btn v-if="!employee&&p.row.status==='Pending'" flat round icon="close" color="negative" @click="reject(p.row)"/></q-td></template></q-table></q-card><q-dialog v-model="dialog"><q-card style="min-width:min(480px,92vw)"><q-card-section class="text-h6">Apply for Leave</q-card-section><q-card-section class="q-gutter-md"><q-select v-model="form.leave_type" outlined label="Leave type" :options="types"/><div class="row q-col-gutter-md"><q-input class="col" v-model="form.start_date" type="date" outlined label="Start date"/><q-input class="col" v-model="form.end_date" type="date" outlined label="End date"/></div><div v-if="days" class="text-caption muted">{{days}} day{{days>1?'s':''}} requested</div><q-input v-model="form.reason" outlined type="textarea" label="Reason (optional)"/></q-card-section><q-card-actions align="right"><q-btn flat label="Cancel" v-close-popup/><q-btn color="primary" label="Submit request" :loading="saving" @click="submit"/></q-card-actions></q-card></q-dialog><q-dialog v-model="rejectDialog"><q-card style="min-width:min(480px,92vw)"><q-card-section class="text-h6">Reject Leave Request</q-card-section><q-card-section class="q-gutter-md"><p class="muted q-mb-sm">Reject the <b>{{pendingReject?.leave_type||'leave'}}</b> request from <b>{{pendingReject?.employee_name||'employee'}}</b>?</p><q-input v-model="rejectionReason" outlined type="textarea" label="Rejection reason (required)" autofocus :error="reasonError" :error-message="reasonError?'A rejection reason is required.':''"/></q-card-section><q-card-actions align="right"><q-btn flat label="Cancel" v-close-popup :disabled="rejecting"/><q-btn color="negative" label="Confirm Reject" :loading="rejecting" @click="confirmReject"/></q-card-actions></q-card></q-dialog></q-page></template>
<script setup>import{ref,computed,onMounted,watch}from'vue';import{useRouter}from'vue-router';import{useQuasar}from'quasar';import{authStore}from'../stores/authStore';import api from'../services/api';const $q=useQuasar(),router=useRouter(),employee=computed(()=>authStore.user?.role==='employee'),rows=ref([]),loading=ref(false),saving=ref(false),filter=ref(null),dialog=ref(false),form=ref({}),rejectDialog=ref(false),rejectionReason=ref(''),rejecting=ref(false),pendingReject=ref(null),reasonError=ref(false),statuses=['Pending','Approved','Rejected','Cancelled'],types=['Annual Leave','Sick Leave','Casual Leave','Unpaid Leave','Other'],cols=[{name:'employee_name',label:'Employee',field:'employee_name',align:'left'},{name:'leave_type',label:'Leave type',field:'leave_type'},{name:'start_date',label:'Start',field:'start_date'},{name:'end_date',label:'End',field:'end_date'},{name:'days',label:'Days',field:'days'},{name:'status',label:'Status',field:'status'},{name:'created_at',label:'Submitted',field:'created_at'},{name:'actions',label:'',field:'actions'}];const days=computed(()=>form.value.start_date&&form.value.end_date?Math.max(0,Math.round((new Date(form.value.end_date)-new Date(form.value.start_date))/86400000)+1):0);async function load(){loading.value=true;try{rows.value=(await api.get('/leaves',{params:{status:filter.value}})).data.data}finally{loading.value=false}}function open(){form.value={leave_type:'Annual Leave',start_date:'',end_date:'',reason:''};dialog.value=true}async function submit(){saving.value=true;try{if(!form.value.leave_type||!form.value.start_date||!form.value.end_date)throw new Error('Complete required fields.');await api.post('/leaves',form.value);dialog.value=false;$q.notify({type:'positive',message:'Leave request submitted'});load()}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||e.message})}finally{saving.value=false}}async function cancel(x){if(!confirm('Cancel this leave request?'))return;try{await api.patch(`/leaves/${x.id}/cancel`);load()}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Unable to cancel'})}}async function review(x,status){try{await api.patch(`/leaves/${x.id}/review`,{status});$q.notify({type:'positive',message:`Leave ${status.toLowerCase()}`});load()}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Unable to review'})}}function reject(x){pendingReject.value=x;rejectionReason.value='';reasonError.value=false;rejectDialog.value=true}async function confirmReject(){reasonError.value=!rejectionReason.value?.trim();if(reasonError.value)return;rejecting.value=true;try{await api.patch(`/leaves/${pendingReject.value.id}/review`,{status:'Rejected',rejection_reason:rejectionReason.value.trim()});rejectDialog.value=false;$q.notify({type:'positive',message:'Leave request rejected'});load()}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Unable to reject leave request'})}finally{rejecting.value=false}}const color=x=>x==='Approved'?'positive':x==='Rejected'?'negative':x==='Cancelled'?'grey-6':'orange';watch(filter,load);onMounted(load)</script>